-- ============================================================
-- IMPORT CATÁLOGO v3 — PARTE 3/5 (490 variantes)
-- Cole no Supabase SQL Editor
-- ============================================================
DO $$
DECLARE v_tenant_id UUID;
BEGIN
  SELECT id INTO v_tenant_id FROM public.tenants LIMIT 1;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Nenhum tenant encontrado.';
  END IF;

  ON CONFLICT (tenant_id, variant_id) DO UPDATE SET
    technical_attributes = EXCLUDED.technical_attributes,
    updated_at = NOW();

  RAISE NOTICE 'Parte 3/5 OK — 490 variantes inseridas.';
END $$;
